use std::fs

fn emit(text: string, number: bool, counter: int) -> int {
    if number {
        let mut c = counter
        for line in text.lines() {
            c += 1
            let s = "${c}"
            let mut pad = ""
            let mut i = s.len() as int
            while i < 6 {
                pad = pad + " "
                i += 1
            }
            println("${pad}${s}\t${line}")
        }
        c
    } else {
        print("${text}")
        counter
    }
}

fn main() {
    let mut number = false
    let mut files: Vec<string> = []
    let mut first = true
    for a in std::env::args() {
        if first {
            first = false
            continue
        }
        if a == "-n" {
            number = true
        } else {
            files.push(a)
        }
    }
    let mut counter = 0
    let mut failed = false
    if files.len() == 0 {
        let text = fs::read_to_string("/dev/stdin").unwrap_or("")
        counter = emit(text, number, counter)
    } else {
        for f in files {
            match fs::read_to_string(f) {
                Ok(text) => {
                    counter = emit(text, number, counter)
                }
                Err(_) => {
                    println("cat: ${f}: No such file")
                    failed = true
                }
            }
        }
    }
    if failed {
        std::process::exit(1)
    }
}

